import{_ as t,c as o,o as r,ax as n}from"./chunks/framework.DHqKNX4U.js";const g=JSON.parse('{"title":"SSO Examples","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/sso/examples/index.md","filePath":"enterprise/sso/examples/index.md"}'),i={name:"enterprise/sso/examples/index.md"};function a(s,e,d,h,c,l){return r(),o("div",null,e[0]||(e[0]=[n('<h1 id="sso-examples" tabindex="-1">SSO Examples <a class="header-anchor" href="#sso-examples" aria-label="Permalink to &quot;SSO Examples&quot;">​</a></h1><p>Complete configuration procedures for the identity providers most Open Archiver customers use. Each example covers both supported protocols, from registering the application at the provider through to verifying the first sign-in and resolving common failures.</p><table tabindex="0"><thead><tr><th>Example</th><th>Protocols</th><th>Group-based roles</th></tr></thead><tbody><tr><td><a href="./google-workspace.html">Google Workspace</a></td><td>OIDC, SAML 2.0</td><td>SAML only</td></tr><tr><td><a href="./google-workspace-okta.html">Google Workspace via Okta</a></td><td>OIDC, SAML 2.0</td><td>Both</td></tr><tr><td><a href="./microsoft-365.html">Microsoft 365 (Entra ID)</a></td><td>OIDC, SAML 2.0</td><td>Both</td></tr><tr><td><a href="./microsoft-365-okta.html">Microsoft 365 via Okta</a></td><td>OIDC, SAML 2.0</td><td>Both</td></tr></tbody></table><h2 id="choosing-an-example" tabindex="-1">Choosing an example <a class="header-anchor" href="#choosing-an-example" aria-label="Permalink to &quot;Choosing an example&quot;">​</a></h2><p><strong>Connect to your identity provider directly</strong> when it is the system that holds your user accounts. This is the shorter path and the usual choice.</p><p><strong>Connect through Okta</strong> when Okta is already your organisation&#39;s identity provider, with Google Workspace or Microsoft 365 federated behind it. Okta also resolves one specific limitation: Google Workspace cannot send group membership over OpenID Connect, so if you want directory groups to determine roles and prefer OpenID Connect to SAML, Okta supplies what Google does not.</p><div class="tip custom-block"><p class="custom-block-title">One connection per identity provider, not per directory</p><p>If Okta, or any other provider, brokers access to several directories, you need only one Open Archiver connection. Add the further directories inside that provider. Creating a separate connection for each directory behind the same provider will not work as expected, because every sign-in resolves to the same account at the brokering provider.</p></div><h2 id="choosing-a-protocol" tabindex="-1">Choosing a protocol <a class="header-anchor" href="#choosing-a-protocol" aria-label="Permalink to &quot;Choosing a protocol&quot;">​</a></h2><p>Where a provider supports both, <strong>OpenID Connect is the simpler choice</strong>: the configuration amounts to one address and two credentials, and Open Archiver reads everything else from the provider automatically.</p><p>Choose SAML 2.0 when your organisation standardises on it, when a compliance requirement names it specifically, or when your provider&#39;s OpenID Connect implementation omits something you need — group membership from Google Workspace being the common case.</p><h2 id="before-you-start-any-example" tabindex="-1">Before you start any example <a class="header-anchor" href="#before-you-start-any-example" aria-label="Permalink to &quot;Before you start any example&quot;">​</a></h2><p>Each example lists its own prerequisites, but three apply throughout:</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Detail</th></tr></thead><tbody><tr><td>License</td><td>Open Archiver Enterprise with the <strong>SSO</strong> feature enabled. Confirm under <strong>Admin → License</strong>.</td></tr><tr><td>Open Archiver role</td><td>Super Admin. Single sign-on is configured under <strong>Admin → Single Sign-On</strong>.</td></tr><tr><td>Application address</td><td><code>APP_URL</code> must be set to the address people use to reach Open Archiver. Every address you register with your provider derives from it.</td></tr></tbody></table><p>Open the connection form in Open Archiver before configuring your identity provider. It displays the exact addresses to register — the redirect URI for OpenID Connect, and the service provider metadata and assertion consumer service addresses for SAML. Copying them from the page avoids the transcription errors that cause most first-attempt failures.</p><h2 id="after-configuring-a-connection" tabindex="-1">After configuring a connection <a class="header-anchor" href="#after-configuring-a-connection" aria-label="Permalink to &quot;After configuring a connection&quot;">​</a></h2><p>Every example ends with the same three steps, and none should be skipped:</p><ol><li><strong>Test the connection</strong> before enabling it. The test confirms Open Archiver can reach your provider and read its configuration, and it reports a specific reason when it cannot.</li><li><strong>Enable the connection</strong>, which adds its button to the sign-in page.</li><li><strong>Verify a sign-in</strong> from a private browser window, then confirm the resulting account and role under <strong>Settings → Users</strong>.</li></ol><p>When a sign-in fails, the person signing in sees only a brief message. The explanation is recorded in <strong>Compliance → Audit Log</strong>, where each failed entry names the connection involved, the address the provider supplied, and the domains the connection permits — usually enough to identify the misconfiguration without further investigation.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../guide.html">SSO guide</a> — the accounts and roles model, running several providers at once, requiring single sign-on, and auditing.</li></ul>',20)]))}const u=t(i,[["render",a]]);export{g as __pageData,u as default};
